section.code:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://faion.net/schemas/java-spring.json",
  "type": "object",
  "required": ["spring_boot_version", "endpoints", "uses_mapstruct", "uses_bcrypt_in_service", "jakarta_imports_only"],
  "properties": {
    "spring_boot_version": {"type": "string", "pattern": "^3\\."},
    "endpoints": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["path", "method", "returns_dto", "list_pageable"],
        "properties": {
          "path": {"type": "string"},
          "method": {"enum": ["GET", "POST", "PUT", "PATCH", "DELETE"]},
          "returns_dto": {"type": "boolean", "const": true},
          "list_pageable": {"type": ["boolean", "null"]},
          "transactional_on_write": {"type": "boolean"}
        }
      }
    },
    "controller": {
      "type": "object",
      "required": ["class_name", "has_transactional", "calls_repository_directly"],
      "properties": {
        "class_name": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+Controller$"},
        "has_transactional": {"type": "boolean", "const": false},
        "calls_repository_directly": {"type": "boolean", "const": false},
        "service_calls_per_method": {"type": "integer", "maximum": 1}
      }
    },
    "request_dto": {
      "type": "object",
      "required": ["class_name", "is_record", "has_bean_validation"],
      "properties": {
        "class_name": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+Request$"},
        "is_record": {"type": "boolean", "const": true},
        "has_bean_validation": {"type": "boolean", "const": true}
      }
    },
    "response_dto": {
      "type": "object",
      "required": ["class_name", "is_record"],
      "properties": {
        "class_name": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+Response$"},
        "is_record": {"type": "boolean", "const": true}
      }
    },
    "async": {
      "type": "object",
      "properties": {
        "self_invocation": {"type": "boolean", "const": false},
        "executor_name": {"type": "string", "minLength": 1},
        "executor_bean_defined": {"type": "boolean", "const": true}
      }
    },
    "errors_use_problemdetail": {"type": "boolean", "const": true},
    "uses_mapstruct": {"type": "boolean", "const": true},
    "uses_bcrypt_in_service": {"type": "boolean", "const": true},
    "jakarta_imports_only": {"type": "boolean", "const": true},
    "forbidden_patterns_found": {"type": "array", "items": {"type": "string"}, "maxItems": 0}
  }
}
